package dev.eugheist.ttmodern;
final class PlacementMirrorPreviewAudit {
 static void run(net.minecraft.client.Minecraft mc){var colors=new java.util.ArrayList<Integer>();var vertices=new java.util.concurrent.atomic.AtomicInteger();var type=com.mojang.blaze3d.vertex.VertexConsumer.class;var sink=(com.mojang.blaze3d.vertex.VertexConsumer)java.lang.reflect.Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},(proxy,method,args)->{if(method.getName().equals("setColor")&&args.length==4)colors.add((Integer)args[3]);if(method.getName().equals("addVertex"))vertices.incrementAndGet();if(method.isDefault())return java.lang.reflect.InvocationHandler.invokeDefault(proxy,method,args);if(method.getReturnType()==type)return proxy;return null;});PlacementMirrorPreview.block(mc,new com.mojang.blaze3d.vertex.PoseStack(),renderType->sink,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());if(vertices.get()==0||colors.isEmpty()||colors.stream().anyMatch(alpha->alpha!=153))throw new IllegalStateException("Original mirror preview alpha on actual native model: vertices="+vertices+",colors="+colors);System.out.println("TT PLACEMENT MIRROR PREVIEW AUDIT: ALL PASS (actual native stone baked model vertices,all alpha153/255)");}
}
